(2614586, 362213, 59095, '<td valign="top">I like this shot.  Problem is his armpit is shining.</td>', 'I like this shot.  Problem is his armpit is shining.', '2006-07-12 12:21:40.000000', NULL, 1),
(2614616, 362524, 41200, '<td valign="top">Very nice photo illustration to make a social comment. 10</td>', 'Very nice photo illustration to make a social comment. 10', '2006-07-12 12:28:06.000000', NULL, 1),
(2614628, 361675, 39349, '<td valign="top">Okay, first off I like the idea you have working for you here. This is really the state of the world we live in now hu? I like the tonal range you''ve captured here, the purple in the car and the yellow orange in the sunset really contrast well with each other. However the green tint in the windows seems to be stealing from the rest of the shot. I''m also distracted by the body line of the car on the top third of the shot. You might want to ease up on the saturation a little too, there seems to be some noise in and around the HYBRID logo. Compositional, I would suggest just focusing on the sunset with the HYBRID as the subject. I think this would keep the focus on your message. Good eye, and a wonderful idea!</td>', 'Okay, first off I like the idea you have working for you here. This is really the state of the world we live in now hu? I like the tonal range you''ve captured here, the purple in the car and the yellow orange in the sunset really contrast well with each other. However the green tint in the windows seems to be stealing from the rest of the shot. I''m also distracted by the body line of the car on the top third of the shot. You might want to ease up on the saturation a little too, there seems to be some noise in and around the HYBRID logo. Compositional, I would suggest just focusing on the sunset with the HYBRID as the subject. I think this would keep the focus on your message. Good eye, and a wonderful idea!', '2006-07-12 12:33:32.000000', NULL, 1),
(2614641, 361568, 39349, '<td valign="top">WOW this is an amazing shot! Not much in the way of change / suggestions I could make here. You''ve nailed this one my friend, congrats on a beautiful portrait that you and the mother to be should be VERY proud of. 10 from me.</td>', 'WOW this is an amazing shot! Not much in the way of change / suggestions I could make here. You''ve nailed this one my friend, congrats on a beautiful portrait that you and the mother to be should be VERY proud of. 10 from me.', '2006-07-12 12:36:33.000000', NULL, 1),
(2614645, 362521, 39349, '<td valign="top">Amazing portrait, those eyes just draw you into the shot. My only suggestions would be to clone out the few distracting hairs (I know your limited here) and maybe crop out the remaining part of her ear. Well done!</td>', 'Amazing portrait, those eyes just draw you into the shot. My only suggestions would be to clone out the few distracting hairs (I know your limited here) and maybe crop out the remaining part of her ear. Well done!', '2006-07-12 12:39:03.000000', NULL, 1),
(2614652, 361123, 60242, '<td valign="top">Great Shot!</td>', 'Great Shot!', '2006-07-12 12:41:21.000000', NULL, 1),
(2614661, 361971, 39349, '<td valign="top">VERY NICE! Great shot for this challenge. My one suggestion would to either skew the horizon line so they are way off balance or level it out. Great job though!</td>', 'VERY NICE! Great shot for this challenge. My one suggestion would to either skew the horizon line so they are way off balance or level it out. Great job though!', '2006-07-12 12:43:07.000000', NULL, 1),
(2614675, 360692, 39349, '<td valign="top">Composition here really isn''t doing much for me, I''m not trying to be too much of a "stickler" here cause I can''t imagine capturing these beauties was easy. With that said, THOSE PLANES are AWESOME! I''m a sucker for WWII stuff and that Corsair makes this shot for me.</td>', 'Composition here really isn''t doing much for me, I''m not trying to be too much of a "stickler" here cause I can''t imagine capturing these beauties was easy. With that said, THOSE PLANES are AWESOME! I''m a sucker for WWII stuff and that Corsair makes this shot for me.', '2006-07-12 12:46:19.000000', NULL, 1),
(2614682, 362515, 42085, '<td valign="top">Freak Yes, The hulk, that''s what i''m talking about</td>', 'Freak Yes, The hulk, that''s what i''m talking about', '2006-07-12 12:48:15.000000', NULL, 1),
