INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2614716, 359868, 57202, '<td valign="top">I like that you used such a shallow DOF to put just those drops in sharp focus. :D  The only improvement I could possibly suggest would be to use levels and possibly desaturation to make the dark tiles completely black.</td>', 'I like that you used such a shallow DOF to put just those drops in sharp focus. :D  The only improvement I could possibly suggest would be to use levels and possibly desaturation to make the dark tiles completely black.', '2006-07-12 13:03:56.000000', NULL, 1),
(2614733, 362325, 57202, '<td valign="top">I LOVE the concept of this picture!  The lighting is great, you have a perfect catch-light in her eyes, and the composition leads you from past memories into the present. :)  The only thing that may have bumped this picture even higher for me is if contrast/levels had been used just a little more to help it "pop" a little more (it seems just a bit low in contrast, though that may just be my monitor... ;) ).  Great job!</td>', 'I LOVE the concept of this picture!  The lighting is great, you have a perfect catch-light in her eyes, and the composition leads you from past memories into the present. :)  The only thing that may have bumped this picture even higher for me is if contrast/levels had been used just a little more to help it "pop" a little more (it seems just a bit low in contrast, though that may just be my monitor... ;) ).  Great job!', '2006-07-12 13:08:24.000000', NULL, 1),
(2614741, 362351, 62016, '<td valign="top">I like this a lot.  I would hang this in my house.</td>', 'I like this a lot.  I would hang this in my house.', '2006-07-12 13:09:25.000000', NULL, 1),
(2614748, 361435, 62016, '<td valign="top">Cool.</td>', 'Cool.', '2006-07-12 13:11:31.000000', NULL, 1),
(2614771, 362134, 39349, '<td valign="top">PPPFFT...<br/> <br/>No, this is what we call over sharpening. Okay all kidding aside, this is a great shot with a great theme, I love your choice of DOF. The pane of glass in the foreground of the shot IMHO takes away from the leading lines you have with the cars, I would re-shoot without the pane of glass and you would really have a wonderful shot. And yes, I would tone down the un-sharpen mask a little, there''s a lot of haloing in the body lines of the background cars and grass reeds. Good eye and a wonderful shot.<br/><br/><i>Message edited by author 2006-07-21 18:02:28.</i></td>', 'PPPFFT... No, this is what we call over sharpening. Okay all kidding aside, this is a great shot with a great theme, I love your choice of DOF. The pane of glass in the foreground of the shot IMHO takes away from the leading lines you have with the cars, I would re-shoot without the pane of glass and you would really have a wonderful shot. And yes, I would tone down the un-sharpen mask a little, there''s a lot of haloing in the body lines of the background cars and grass reeds. Good eye and a wonderful shot.', '2006-07-12 13:17:58.000000', '2006-07-21 19:02:28.000000', 1),
(2614772, 362378, 57202, '<td valign="top">An excellent example of progress! :)  I like that you used such tight DOF to really show the texture on the record.  Personally, this would have scored even higher with me if a drop shadow hadn''t been used along the edges and if a solid, even-width border had been used.</td>', 'An excellent example of progress! :)  I like that you used such tight DOF to really show the texture on the record.  Personally, this would have scored even higher with me if a drop shadow hadn''t been used along the edges and if a solid, even-width border had been used.', '2006-07-12 13:18:05.000000', NULL, 1),
(2614778, 362294, 39349, '<td valign="top">Great shot, good take on this challenge. I like your lighting, it provides this shot with great tonal range. Good choice on the DOF as well. My one suggestion would be to not have cropped out her elbow. Other than that, well done!</td>', 'Great shot, good take on this challenge. I like your lighting, it provides this shot with great tonal range. Good choice on the DOF as well. My one suggestion would be to not have cropped out her elbow. Other than that, well done!', '2006-07-12 13:19:43.000000', NULL, 1),
(2614784, 362246, 57202, '<td valign="top">Extremely sharp focus, nice composition, and eye-popping rich colors.  Well done!</td>', 'Extremely sharp focus, nice composition, and eye-popping rich colors.  Well done!', '2006-07-12 13:22:51.000000', NULL, 1),
(2614787, 361670, 39349, '<td valign="top">Great selective desaturation, one of the best I''ve seen here in a long time! Composition is pretty good, I would suggest that you didn''t crop / frame out the bottom of his boot.</td>', 'Great selective desaturation, one of the best I''ve seen here in a long time! Composition is pretty good, I would suggest that you didn''t crop / frame out the bottom of his boot.', '2006-07-12 13:23:28.000000', NULL, 1),
(2614798, 359608, 57202, '<td valign="top">LMAO!  Great capture! :)</td>', 'LMAO!  Great capture! :)', '2006-07-12 13:26:51.000000', NULL, 1),
(2614812, 361491, 57320, '<td valign="top">Soooo sad! Good focus and stuff, but is the bunny reakkt there it looks edited. I think I might go and cry.</td>', 'Soooo sad! Good focus and stuff, but is the bunny reakkt there it looks edited. I think I might go and cry.', '2006-07-12 13:32:53.000000', NULL, 1),
(2614814, 362294, 57202, '<td valign="top">What a wonderful photo! :)  The DOF is great, the composition excellent, it perfectly meets the challenge, and the expression on her face is priceless! :D</td>', 'What a wonderful photo! :)  The DOF is great, the composition excellent, it perfectly meets the challenge, and the expression on her face is priceless! :D', '2006-07-12 13:33:06.000000', NULL, 1),
