(2615511, 359608, 60995, '<td valign="top">Hee hee.</td>', 'Hee hee.', '2006-07-12 16:52:09.000000', NULL, 1),
(2615517, 362521, 24991, '<td valign="top">It''s a good shot, great perspective and all, but you could use some serious work on your lighting.  Looks like you''re using a soft-box...ok, softboxes are good.  But you could be much more creative with the way that shadows are cast on the models face.</td>', 'It''s a good shot, great perspective and all, but you could use some serious work on your lighting.  Looks like you''re using a soft-box...ok, softboxes are good.  But you could be much more creative with the way that shadows are cast on the models face.', '2006-07-12 16:52:42.000000', NULL, 1),
