INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2616497, 361123, 45360, '<td valign="top">Fantastic shot.  8 from me.</td>', 'Fantastic shot.  8 from me.', '2006-07-12 21:14:01.000000', NULL, 1),
(2616507, 362494, 8624, '<td valign="top">beautiful lighting</td>', 'beautiful lighting', '2006-07-12 21:19:25.000000', NULL, 1),
(2616514, 361962, 8624, '<td valign="top">I like the idea here a lot and the vials of water and the grid base are visually interesting, but I find the smoky, fractally background thing a bit distracting. I think it needs some background element, which is nicely refracted in the water, but this particular pattern doesn''t work for me.</td>', 'I like the idea here a lot and the vials of water and the grid base are visually interesting, but I find the smoky, fractally background thing a bit distracting. I think it needs some background element, which is nicely refracted in the water, but this particular pattern doesn''t work for me.', '2006-07-12 21:21:29.000000', NULL, 1),
(2616519, 362531, 8624, '<td valign="top">clever! I''d like to see this bigger - I think the wide pano crop on such a small image loses detail, but your concept is well expressed.</td>', 'clever! I''d like to see this bigger - I think the wide pano crop on such a small image loses detail, but your concept is well expressed.', '2006-07-12 21:22:51.000000', NULL, 1),
