(2618447, 362134, 61818, '<td valign="top">I like this shot.  Think it would have worked a little better with the focus on the car half way up the right side rather than the one at the bottom, but overall very nice.</td>', 'I like this shot.  Think it would have worked a little better with the focus on the car half way up the right side rather than the one at the bottom, but overall very nice.', '2006-07-13 10:59:37.000000', NULL, 1),
(2618457, 361608, 61818, '<td valign="top">Nice shot and concept, but the lack of contrast between the rubble pile and the church sort of takes away from the effect.</td>', 'Nice shot and concept, but the lack of contrast between the rubble pile and the church sort of takes away from the effect.', '2006-07-13 11:02:30.000000', NULL, 1),
