(2630220, 361962, 45790, '<td valign="top">Very mysterious! Makes me wonder how you made the smoke in the background.</td>', 'Very mysterious! Makes me wonder how you made the smoke in the background.', '2006-07-17 15:02:44.000000', NULL, 1),
(2630222, 362229, 45790, '<td valign="top">I don''t know what it is, but I like the composition and colors.</td>', 'I don''t know what it is, but I like the composition and colors.', '2006-07-17 15:03:21.000000', NULL, 1),
(2630224, 361151, 45790, '<td valign="top">Great irony! Could use slightly less exposure.</td>', 'Great irony! Could use slightly less exposure.', '2006-07-17 15:04:56.000000', NULL, 1),
(2630234, 362387, 45790, '<td valign="top">I like composition, but wonder if it would have been better in color -- the climber blends in with the structure.</td>', 'I like composition, but wonder if it would have been better in color -- the climber blends in with the structure.', '2006-07-17 15:06:30.000000', NULL, 1),
(2630236, 362148, 45790, '<td valign="top">Fun composition and great choice of contrasting background color.</td>', 'Fun composition and great choice of contrasting background color.', '2006-07-17 15:07:05.000000', NULL, 1),
(2630237, 362387, 24073, '<td valign="top">I think this is too busy.  I think subtracting alot of this photo would be necessary to bank votes.<br/> <br/>The power lines, the chain in front, the subjects, the cars in the background, all of this could of been gone with a much better result IMHO.</td>', 'I think this is too busy.  I think subtracting alot of this photo would be necessary to bank votes. The power lines, the chain in front, the subjects, the cars in the background, all of this could of been gone with a much better result IMHO.', '2006-07-17 15:07:16.000000', NULL, 1),
(2630238, 362353, 45790, '<td valign="top">No, you can''t be DQed for DNMC :-) But, sorry, there is nothing that makes this stand out from other brown ribbon winners in the past.</td>', 'No, you can''t be DQed for DNMC :-) But, sorry, there is nothing that makes this stand out from other brown ribbon winners in the past.', '2006-07-17 15:07:23.000000', NULL, 1),
(2630239, 362099, 45790, '<td valign="top">Or if you tilt it the other way, upward progress? There is no frame of reference here to tell.</td>', 'Or if you tilt it the other way, upward progress? There is no frame of reference here to tell.', '2006-07-17 15:07:30.000000', NULL, 1),
(2630240, 362326, 45790, '<td valign="top">Climber is small and blends with the rocks -- too hard to spot. In closer, and maybe in portrait orientation, it would be easier to see.</td>', 'Climber is small and blends with the rocks -- too hard to spot. In closer, and maybe in portrait orientation, it would be easier to see.', '2006-07-17 15:07:58.000000', NULL, 1),
