INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2630242, 362025, 45790, '<td valign="top">Is the lighting green? She has a green left wrist, chin, neck, eyebrow, and streaks in her hair.</td>', 'Is the lighting green? She has a green left wrist, chin, neck, eyebrow, and streaks in her hair.', '2006-07-17 15:08:29.000000', NULL, 1),
(2630244, 362050, 45790, '<td valign="top">This idea is getting way too overused.</td>', 'This idea is getting way too overused.', '2006-07-17 15:09:49.000000', NULL, 1),
(2630246, 362042, 45790, '<td valign="top">Probably takes special knowledge to understand this one.</td>', 'Probably takes special knowledge to understand this one.', '2006-07-17 15:09:58.000000', NULL, 1),
(2630248, 362345, 45790, '<td valign="top">I''d like to be able to see the woman better.</td>', 'I''d like to be able to see the woman better.', '2006-07-17 15:12:04.000000', NULL, 1),
(2630249, 360335, 24073, '<td valign="top">OK.  Well this is smack you in the face terrific.  Not alot to complain about here, but you do have some noise.  Very reckognizable in the bluest part of the sky.  Did you use a high ISO?  If so you probably could of lowered it and slowed the shutterspeed with the same result subtracting the noise.  I''m still betting on a top 15% finish.  I have voted on 25%, and its my fav so far.  GL.  Brilliant color, and depth by the way.</td>', 'OK.  Well this is smack you in the face terrific.  Not alot to complain about here, but you do have some noise.  Very reckognizable in the bluest part of the sky.  Did you use a high ISO?  If so you probably could of lowered it and slowed the shutterspeed with the same result subtracting the noise.  I''m still betting on a top 15% finish.  I have voted on 25%, and its my fav so far.  GL.  Brilliant color, and depth by the way.', '2006-07-17 15:12:06.000000', NULL, 1),
(2630252, 362063, 45790, '<td valign="top">Good use of monochrome. Nice framing.</td>', 'Good use of monochrome. Nice framing.', '2006-07-17 15:12:47.000000', NULL, 1),
(2630254, 362367, 24073, '<td valign="top">Wow, the capture in this is amazing.  I will be rooting for you.  GL.</td>', 'Wow, the capture in this is amazing.  I will be rooting for you.  GL.', '2006-07-17 15:13:06.000000', NULL, 1),
(2630258, 359184, 45790, '<td valign="top">The bigger/newer is about the dullest building I''ve ever seen! Great find and nicely done.</td>', 'The bigger/newer is about the dullest building I''ve ever seen! Great find and nicely done.', '2006-07-17 15:14:10.000000', NULL, 1),
(2630265, 362035, 24073, '<td valign="top">Very outside the box, and creative.</td>', 'Very outside the box, and creative.', '2006-07-17 15:16:20.000000', NULL, 1),
