(2630275, 362131, 24073, '<td valign="top">Disturbing.  I dont know why, it just has an over the top element for me.  GL.</td>', 'Disturbing.  I dont know why, it just has an over the top element for me.  GL.', '2006-07-17 15:18:29.000000', NULL, 1),
(2630280, 362099, 24073, '<td valign="top">You have the magic stand out element on this.  It would be hard to vote this less than 6 for anybody, I personally think its an 8.</td>', 'You have the magic stand out element on this.  It would be hard to vote this less than 6 for anybody, I personally think its an 8.', '2006-07-17 15:21:04.000000', NULL, 1),
