(2633777, 360357, 60027, '<td valign="top">I like the relationship between the Day''s.  Good photo.</td>', 'I like the relationship between the Day''s.  Good photo.', '2006-07-18 18:24:08.000000', NULL, 1),
(2633779, 362162, 31133, '<td valign="top">I think this would''ve been more effective without the barrier in the background, for example if you would''ve stood a bit to the left (not always possible, I realize). I wonder how it would be without the pole also, such as right up close to the sign, with just a bit of dirt and pavement to make your point.</td>', 'I think this would''ve been more effective without the barrier in the background, for example if you would''ve stood a bit to the left (not always possible, I realize). I wonder how it would be without the pole also, such as right up close to the sign, with just a bit of dirt and pavement to make your point.', '2006-07-18 18:24:21.000000', NULL, 1),
(2633784, 361459, 60027, '<td valign="top">I love this picture.  I like the contrast with such obvious suffering and a party hat.</td>', 'I love this picture.  I like the contrast with such obvious suffering and a party hat.', '2006-07-18 18:25:16.000000', NULL, 1),
(2633785, 362351, 31133, '<td valign="top">Very pretty, especially the bokeh in the background.</td>', 'Very pretty, especially the bokeh in the background.', '2006-07-18 18:25:19.000000', NULL, 1),
(2633787, 362449, 60027, '<td valign="top">I like this comparison.  What a long way we''ve come.</td>', 'I like this comparison.  What a long way we''ve come.', '2006-07-18 18:26:10.000000', NULL, 1),
(2633790, 362058, 31133, '<td valign="top">Boy, this meets the challenge perfectly! For my taste, a bit less grain would be awesome, but maybe you intended to have the graininess. I really like the tones and the fact that the little girl is looking right into the camera. The angle of the hand and the way you cropped it at an angle adds a nice dynamic to the image.</td>', 'Boy, this meets the challenge perfectly! For my taste, a bit less grain would be awesome, but maybe you intended to have the graininess. I really like the tones and the fact that the little girl is looking right into the camera. The angle of the hand and the way you cropped it at an angle adds a nice dynamic to the image.', '2006-07-18 18:27:34.000000', NULL, 1),
(2633795, 360209, 60027, '<td valign="top">Beautiful colors in this shot.</td>', 'Beautiful colors in this shot.', '2006-07-18 18:28:07.000000', NULL, 1),
(2633798, 359277, 60027, '<td valign="top">This is a great idea!  I like this picture</td>', 'This is a great idea!  I like this picture', '2006-07-18 18:29:54.000000', NULL, 1),
(2633807, 362484, 31133, '<td valign="top">This doesn''t do much for me, unfortunately. My reasons for saying this include that the reddish dirt where my eye is drawn is kind of out of focus, and the sawed-off part of the tree is a little glary. Also, all the brush that is in pretty sharp focus is distracting and makes me a little confused by the subject at first glance. It might be nice to try this with a larger apeture (smaller number) to get the twigs in the background more out of focus compared to the tree stump. The idea is okay, though and I think the title is clever.</td>', 'This doesn''t do much for me, unfortunately. My reasons for saying this include that the reddish dirt where my eye is drawn is kind of out of focus, and the sawed-off part of the tree is a little glary. Also, all the brush that is in pretty sharp focus is distracting and makes me a little confused by the subject at first glance. It might be nice to try this with a larger apeture (smaller number) to get the twigs in the background more out of focus compared to the tree stump. The idea is okay, though and I think the title is clever.', '2006-07-18 18:31:51.000000', NULL, 1),
(2633811, 362175, 31133, '<td valign="top">Really nice image! What a capture of intense concentration you got. I like the perspective that the person in the background adds. Only niggle is that I wish I could see his hands. Favorite part is that purple rope that draws my eye right in to the climber.</td>', 'Really nice image! What a capture of intense concentration you got. I like the perspective that the person in the background adds. Only niggle is that I wish I could see his hands. Favorite part is that purple rope that draws my eye right in to the climber.', '2006-07-18 18:34:07.000000', NULL, 1),
(2633814, 362510, 31133, '<td valign="top">Amazing! This would''ve done well in the abstract food challenge too! I guess I''m going to have to make this a favorite.</td>', 'Amazing! This would''ve done well in the abstract food challenge too! I guess I''m going to have to make this a favorite.', '2006-07-18 18:36:13.000000', NULL, 1),
(2633815, 362294, 31133, '<td valign="top">Wow, another favorite! What an awesome perspective and expression. Great tones, too.</td>', 'Wow, another favorite! What an awesome perspective and expression. Great tones, too.', '2006-07-18 18:39:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2633817, 362209, 31133, '<td valign="top">Great thumb. This is very nicely done.</td>', 'Great thumb. This is very nicely done.', '2006-07-18 18:41:39.000000', NULL, 1),
(2633822, 362194, 31133, '<td valign="top">I think this might be more effective (for my taste) to go out a little to get the entire objects in the frame, or alternatively, in much closer to get just the wheels or some other small but identifying part. The glare on the car and the small bit of road in the background is kind of distracting. You met the challenge topic and did well with the sharpness and the colors, though.</td>', 'I think this might be more effective (for my taste) to go out a little to get the entire objects in the frame, or alternatively, in much closer to get just the wheels or some other small but identifying part. The glare on the car and the small bit of road in the background is kind of distracting. You met the challenge topic and did well with the sharpness and the colors, though.', '2006-07-18 18:44:55.000000', NULL, 1),
(2633829, 362035, 31133, '<td valign="top">I love how this meets the challenge topic so well that I could guess the topic just by looking at the image alone, not knowing in advance. The big drawback for me is the static centering of the billboard. I believe the image would be much more dynamic if it were quite a bit farther to the left of center. The cracked dirt contrasted with that lovely and natural portrait is powerful.</td>', 'I love how this meets the challenge topic so well that I could guess the topic just by looking at the image alone, not knowing in advance. The big drawback for me is the static centering of the billboard. I believe the image would be much more dynamic if it were quite a bit farther to the left of center. The cracked dirt contrasted with that lovely and natural portrait is powerful.', '2006-07-18 18:48:17.000000', NULL, 1),
(2633839, 362508, 46314, '<td valign="top">Do you own an iPod store or something?</td>', 'Do you own an iPod store or something?', '2006-07-18 18:51:04.000000', NULL, 1),
(2633854, 362497, 46314, '<td valign="top">Focus could bit a bit sharper.</td>', 'Focus could bit a bit sharper.', '2006-07-18 18:58:06.000000', NULL, 1),
(2633899, 362531, 59342, '<td valign="top">Gotta give you mucho credit for your creativity.  This picture definetely made me smile</td>', 'Gotta give you mucho credit for your creativity.  This picture definetely made me smile', '2006-07-18 19:17:38.000000', NULL, 1),
(2633910, 362537, 59342, '<td valign="top">What a great image.  I didn''t realize the challenge of aquarium photography until this past weekend.  Kuddos on the quality, sharpness, colors, and set up.</td>', 'What a great image.  I didn''t realize the challenge of aquarium photography until this past weekend.  Kuddos on the quality, sharpness, colors, and set up.', '2006-07-18 19:20:41.000000', NULL, 1),
(2633921, 362381, 46314, '<td valign="top">Very nice colours.</td>', 'Very nice colours.', '2006-07-18 19:26:09.000000', NULL, 1),
(2633922, 362208, 38032, '<td valign="top">I like it ... where does one get a snail with such a great shell?</td>', 'I like it ... where does one get a snail with such a great shell?', '2006-07-18 19:28:07.000000', NULL, 1),
(2633923, 360289, 60332, '<td valign="top">Býr Íslendingur hér?</td>', 'Býr Íslendingur hér?', '2006-07-18 19:28:12.000000', NULL, 1),
(2633924, 362486, 38032, '<td valign="top">I like the parallel you found to music.</td>', 'I like the parallel you found to music.', '2006-07-18 19:28:46.000000', NULL, 1),
