(2633965, 361971, 46314, '<td valign="top">The photo would have been better if it had been more candid. In other words, if the subjects had been involved in what they were doing, rather than looking directly at the camera.</td>', 'The photo would have been better if it had been more candid. In other words, if the subjects had been involved in what they were doing, rather than looking directly at the camera.', '2006-07-18 19:48:54.000000', NULL, 1),
(2633970, 362176, 46314, '<td valign="top">Like the reflection of the crane - neatly symbolises the continuing construction.</td>', 'Like the reflection of the crane - neatly symbolises the continuing construction.', '2006-07-18 19:52:47.000000', NULL, 1),
(2633978, 361488, 46314, '<td valign="top">Very clever shot. Good work.</td>', 'Very clever shot. Good work.', '2006-07-18 19:55:51.000000', NULL, 1),
