(2634045, 362515, 50695, '<td valign="top">great angle. you should have used this in the perspective challenge. but I can imagine a connection to "progress" so I''ll give you a 9</td>', 'great angle. you should have used this in the perspective challenge. but I can imagine a connection to "progress" so I''ll give you a 9', '2006-07-18 20:48:26.000000', NULL, 1),
(2634046, 359608, 50695, '<td valign="top">7 for making me laugh!</td>', '7 for making me laugh!', '2006-07-18 20:48:29.000000', NULL, 1),
(2634047, 359150, 50695, '<td valign="top">fascinating composition. i like the washed-out quality... it creates a glowing sort of ethereality.</td>', 'fascinating composition. i like the washed-out quality... it creates a glowing sort of ethereality.', '2006-07-18 20:48:33.000000', NULL, 1),
(2634048, 361053, 50695, '<td valign="top">this picture tells a story, creates a world. 7</td>', 'this picture tells a story, creates a world. 7', '2006-07-18 20:48:57.000000', NULL, 1),
(2634052, 362134, 50695, '<td valign="top">somehow that foregrounded piece of glass ties the whole picture together for me. a wonderful collage of color and shape. 8</td>', 'somehow that foregrounded piece of glass ties the whole picture together for me. a wonderful collage of color and shape. 8', '2006-07-18 20:49:50.000000', NULL, 1),
