INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2636631, 362104, 35947, '<td valign="top">I didn''t vote on this challenge but since you requested comments I''ll give you my 2 cents.<br/> <br/>It seems like a snapshot, which often isn''t voted well in challenges.  I''d second the comments made about his hand in his face, it doesn''t look right.  <br/> <br/>Here''s how I would have voted it:<br/>Meets Challenge 1/1<br/>Technical 1/3<br/>Aesthetics 0/1<br/>Composition 1/3<br/>Creativeness/Wow factor 0/2<br/></td>', 'I didn''t vote on this challenge but since you requested comments I''ll give you my 2 cents. It seems like a snapshot, which often isn''t voted well in challenges.  I''d second the comments made about his hand in his face, it doesn''t look right.   Here''s how I would have voted it:Meets Challenge 1/1Technical 1/3Aesthetics 0/1Composition 1/3Creativeness/Wow factor 0/2', '2006-07-19 09:07:10.000000', NULL, 0),
